function openOperator(c){if(!c)return setView("radar");state.controlRunId=c.run_id;if(c.phase===2)return openDemandValidation(c.run_id);if(c.phase===3)return openOpportunityDecision(c.run_id);if(c.phase===4||c.phase===5)return openAssetProduction(c.run_id);if(c.phase>=6)return setView("leads");return setView(c.phase<=1?"radar":"campaigns")}
function loadAdvanced(c,phase){if(c)state.controlRunId=c.run_id;if(c&&!phase){openOperator(c);return}if((phase||"").includes("PHASE 2")){openDemandValidation(c?.run_id||state.controlRunId);return}setView("advanced");const sel=document.querySelector("#run-selector");if(c&&sel){sel.value=c.run_id;sel.dispatchEvent(new Event("change",{bubbles:true}))}setTimeout(()=>{const buttons=[...document.querySelectorAll("#phase-rail button")];const match=buttons.find(b=>b.textContent.includes(phase||`PHASE ${c?.phase||1}`));if(match)match.click()},100)}
function bindRows(selector){document.querySelectorAll(`${selector} .dop-row`).forEach(r=>r.onclick=()=>{const c=state.campaigns.find(x=>x.run_id===r.dataset.run);if(!c)return;state.selected=c;renderLists();renderDetail(c)})}
