const leads=state.campaigns.filter(c=>["lead_captured","awaiting_winner_detection","winner_detected"].includes(c.state)||c.phase>=6);document.querySelector("#dop-lead-list").innerHTML=leads.length?leads.map(c=>`<div class="dop-group"><div><b>${esc(targetName(c))}</b><small>${esc(c.action)}</small></div><button class="btn btn--secondary" data-load="${esc(c.run_id)}">Open lead controls</button></div>`).join(""):'<p class="dop-empty">No real consumer lead has been recorded yet.</p>';
